definition.script:
node {
  stage('checkout') { git url: 'http://gitea:3000/ci/stoa-labs.git', branch: 'main' }
  stage('api-request') {
    withCredentials([string(credentialsId: 'gitea-provision-token', variable: 'GITEA_TOKEN')]) {
      // Les paramètres passent par l'ENVIRONNEMENT, jamais interpolés dans la
      // chaîne sh : saisie humaine = donnée d'un tiers (même règle que
      // team-request.sh/provision-request.sh). API_VERSION/API_BASE/NEW_VERSION
      // vides selon ACTION sont passés tels quels — le script les valide par
      // mode, aucune dérivation Groovy silencieuse ici.
      withEnv(["ACTION=${params.ACTION}", "TEAM=${params.TEAM ?: ''}",
               "API_NAME=${params.API_NAME}", "API_VERSION=${params.API_VERSION ?: ''}",
               "API_BASE=${params.API_BASE ?: ''}", "NEW_VERSION=${params.NEW_VERSION ?: ''}",
               "OPENAPI_SPEC=${params.OPENAPI_SPEC ?: ''}", "INBOUND_MODE=${params.INBOUND_MODE}",
               // lien humain-cliquable dans le commentaire de PR (même
               // convention que team-request.job.xml/team-apply.job.xml) :
               // sans lui, api-request.sh retombe sur GIT_HOST (nom interne
               // au cluster, non résolu hors des conteneurs).
               "GIT_WEB_HOST=http://localhost:13000"]) {
        dir('poc-control-plane-federation') { sh 'set +x; bash scripts/api-request.sh' }
      }
    }
  }
}
